import{z as s,x as B,o as i,c as p,q as t,j as E,D as e,d as l,s as n,S as o}from"./chunks/framework.C8m1ZpeB.js";const I=JSON.parse('{"title":"像差对 NILS 的敏感度","description":"","frontmatter":{"title":"像差对 NILS 的敏感度","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/aberration-nils-sensitivity.md","filePath":"litho/aberration-nils-sensitivity.md","lastUpdated":1791063341000}'),A={name:"litho/aberration-nils-sensitivity.md"};function h(d,a,S,c,_,m){const r=B("Mermaid");return i(),p("div",null,[a[2]||(a[2]=t('<h1 id="像差对-nils-的敏感度" tabindex="-1">像差对 NILS 的敏感度 <a class="header-anchor" href="#像差对-nils-的敏感度" aria-label="Permalink to &quot;像差对 NILS 的敏感度&quot;">​</a></h1><div class="epigraph"><p>Zernike 系数改的是光瞳相位；工艺看见的是阈值处斜率掉了多少。敏感度是把 $c_j$ 接到 NILS 的导数，不是再报一次 RMS 波前。</p><footer>—— Zernike 展开见 Malacara；NILS 定义见 Mack；相位进 TCC 见 Hopkins</footer></div><p><a href="/litho/immersion-vector-imaging">上一课</a>把浸没默认成矢量能量沉积。缺口是：镜头残差、热漂移、离焦配平，最终要问<strong>边还陡不陡</strong>。主干已有 <a href="/litho/nils-ils">NILS</a> 与 <a href="/litho/zernike-aberrations">Zernike</a>；本课补的是二者之间的敏感度，不重定义 ILS，不重背全套多项式。焦面倾斜与场曲如何补偿，留给<a href="/litho/focus-tilt-compensation">下一课</a>。不重推产线 CD 式。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>NILS \\(=\\mathrm{CD}\\cdot(d\\ln I/dx)|_{\\mathrm{th}}\\)。像差进 \\(P\\) 的相位，因而进每条 SOCS 核，空中像边沿变缓或侧移。波前 RMS 或 Strehl 是积分指标，对「这条金属边」不必敏感：同样的 RMS，球差与彗差对密线 NILS 的伤害可以差一截。缺口因此是 \\(\\partial\\mathrm{NILS}/\\partial c_j\\)（以及 \\(\\partial x_\\mathrm{edge}/\\partial c_j\\)），而不是再展开一次 \\(W=\\sum c_j Z_j\\)。</p><p><span class="marginnote">术语翻译：NILS（归一化像对数斜率）量的是阈值处「光强爬坡有多陡」。NILS=3 就是把曝光能量拉高 1%，边位置大约只动千分之三的量级——数字越大，剂量误差越不容易变成 CD 误差。</span></p><p>必须声明图形与阈值：孤立线、密栅、孔、线端各有一套敏感度。浸没矢量像上，TM 已经矮了一截的边，同样 \\(c_j\\) 可以更快把 NILS 打穿。</p><h3 id="偶项与奇项" tabindex="-1">偶项与奇项 <a class="header-anchor" href="#偶项与奇项" aria-label="Permalink to &quot;偶项与奇项&quot;">​</a></h3><p>离焦、球差、像散（偶次、随焦点可配平的一类）主要糊对比、关焦窗。彗差、三叶、倾斜（奇项）主要造成边位移和左右不对称，套刻与 CD 不对称一起动。把所有 \\(c_j\\) 塞进一个「像差预算纳米」而不分偶奇，会同时去拧调焦和对准。</p><p><span class="marginnote">数字实例：193 nm 下 \\(\\lambda/14\\) 的 RMS 波前约 14 nm——这是 Marechal 判据（Strehl≈0.8）的镜头验收线；而对敏感图形，远小于它的单项像差就足以让 NILS 明显下滑。所以「验收合格」与「这条边好用」是两句话。</span></p><p><span class="marginnote">Fringe 与 Noll 编号不同，敏感度表必须写约定。场点不同系数不同：狭缝中心的球差表不能代表狭缝边缘的彗差。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>在校准过的前向（矢量 TCC + 薄膜）上，对每个 \\(c_j\\) 做小扰动，量目标图形阈值处的 NILS 与边位置。线性区给出敏感度系数；大像差要看 Bossung 与 PV-band，线性不够。扫描平均把瞬时波前沿狭缝积分，有效敏感度是加权后的。</p><p>计算光刻：PW-OPC 的工艺点应包含代表像差的焦点与剂量，而不是假定 \\(c_j\\equiv 0\\) 的理想核。镜头加热导致 \\(c_j(t)\\)，敏感度高的项必须进补偿环（下一课的倾斜/场曲是其中可驱动的部分）。</p>',14)),(i(),E(o,null,{default:e(()=>[n(r,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20TD%0A%20%20Z%5B%22Zernike%20cj%22%5D%20--%3E%20P%5B%22%E5%85%89%E7%9E%B3%E7%9B%B8%E4%BD%8D%22%5D%0A%20%20P%20--%3E%20I%5B%22%E7%A9%BA%E4%B8%AD%E5%83%8F%20I%22%5D%0A%20%20I%20--%3E%20NILS%5B%22%E9%98%88%E5%80%BC%20NILS%22%5D%0A%20%20I%20--%3E%20EDGE%5B%22%E8%BE%B9%E4%BD%8D%E7%BD%AE%22%5D%0A%20%20NILS%20--%3E%20SENS%5B%22%E2%88%82NILS%2F%E2%88%82cj%22%5D%0A%20%20EDGE%20--%3E%20SENS%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t('<h3 id="与-mtf-敏感度的差别" tabindex="-1">与 MTF 敏感度的差别 <a class="header-anchor" href="#与-mtf-敏感度的差别" aria-label="Permalink to &quot;与 MTF 敏感度的差别&quot;">​</a></h3><p>OTF 随像差掉的是正弦调制；NILS 是局部对数斜率。通带里 MTF 看起来还能用，切在拐角或线端的缓坡上 NILS 可以已经死。敏感度分析必须在真实图形上做，不能用圆孔 MTF 零点代替。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>相位在光瞳径向的弯曲改变不同空间频率的相对相位，空域干涉从「同相相长」变成错位，边的傅里叶合成变钝。彗差让光瞳一侧的频率多走相位，边向一侧爬，看起来像局部套刻。这就是为什么 EPE（后课）会把像差项和 overlay 项缠在一起：奇像差本来就在挪边。</p><p><span class="marginnote">常见误区：初学者容易以为「波前 RMS 小就万事大吉」。同样大小的 RMS，彗差可以把边悄悄挪出套刻预算，球差却只是糊掉对比——单一 RMS 数字里看不出这种差别，必须看分项敏感度。</span></p>',5)),(i(),E(o,null,{default:e(()=>[n(r,{id:"mermaid-56",class:"mermaid",graph:"flowchart%20TD%0A%20%20AB%5B%22Zernike%20%E7%B3%BB%E6%95%B0%20cj%22%5D%20--%3E%20EVEN%5B%22%E5%81%B6%E9%A1%B9%EF%BC%9A%E7%A6%BB%E7%84%A6%20%2F%20%E7%90%83%E5%B7%AE%20%2F%20%E5%83%8F%E6%95%A3%22%5D%0A%20%20AB%20--%3E%20ODD%5B%22%E5%A5%87%E9%A1%B9%EF%BC%9A%E5%BD%97%E5%B7%AE%20%2F%20%E4%B8%89%E5%8F%B6%20%2F%20%E5%80%BE%E6%96%9C%22%5D%0A%20%20EVEN%20--%3E%20BLUR%5B%22%E8%BE%B9%E5%8F%98%E7%BC%93%E3%80%81%E5%AF%B9%E6%AF%94%E6%8E%89%22%5D%0A%20%20EVEN%20--%3E%20BAL%5B%22%E5%8F%AF%E7%94%A8%E7%84%A6%E7%82%B9%E5%81%8F%E7%BD%AE%E9%85%8D%E5%B9%B3%22%5D%0A%20%20ODD%20--%3E%20SHIFT%5B%22%E8%BE%B9%E4%BE%A7%E7%A7%BB%EF%BC%9A%E5%83%8F%E5%B1%80%E9%83%A8%E5%A5%97%E5%88%BB%22%5D%0A%20%20ODD%20--%3E%20ASYM%5B%22%E5%B7%A6%E5%8F%B3%20CD%20%E4%B8%8D%E5%AF%B9%E7%A7%B0%22%5D%0A%20%20BLUR%20--%3E%20DOF%5B%22%E5%90%83%E7%84%A6%E6%B7%B1%E9%A2%84%E7%AE%97%22%5D%0A%20%20SHIFT%20--%3E%20OV%5B%22%E4%B8%8E%20overlay%20%E9%A1%B9%E7%BA%A0%E7%BC%A0%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[l(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=t('<p>高阶项振荡快，对靠近截止的密图形更毒；低阶项对孤立边和焦窗更毒。敏感度随节距走，禁戒节距附近导数可以变号——照明一换，表要重做。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不给某代投影物镜的系数预算。Strehl 与 Marechal 判据是镜头验收语言，不是 NILS 敏感度。胶扩散会再糊一层，光学敏感度是上限。禁止把未公开的「Zernike 每毫波对应几纳米 CD」当作通用常数。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>像差敏感度是 \\(\\partial\\mathrm{NILS}/\\partial c_j\\) 与边位移，不是单靠 RMS。</li><li>偶项糊窗，奇项挪边；图形类别必须声明。</li><li>矢量浸没像上同样 \\(c_j\\) 可以更狠。</li><li>MTF 掉不代替阈值斜率掉。</li><li>下一课：倾斜与场曲作为可补偿的场相关项。</li><li>出处：Mack（NILS）；Malacara（Zernike）；Hopkins（相位进核）。</li></ul>',5))])}const N=s(A,[["render",h]]);export{I as __pageData,N as default};
